<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {api,newKey} from '../api'
import {useRequestScope} from '../platform/request-scope'
import PageHeader from '../workspace/PageHeader.vue'
const route=useRoute(),capture=useRequestScope(),items=ref<any[]>([]),notices=ref<any[]>([]),admin=ref(false),manage=ref(false),subject=ref(''),description=ref(''),attach=ref(''),diagnostics=ref(true),busy=ref(false),error=ref(''),notice=ref(''),offset=ref(0),total=ref(0),replies=ref<Record<string,string>>({})
let key=newKey(),intentBody=''
const nextNotices=ref<number|null>(null)
async function olderNotices(){if(nextNotices.value===null)return;const scope=capture();try{const result=await api<any>('/experience/notices?offset='+nextNotices.value);if(scope.valid()){notices.value=[...notices.value,...result.items.filter((n:any)=>!notices.value.some(x=>x.id===n.id))];nextNotices.value=result.nextOffset}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function load(){const scope=capture();error.value='';try{const [list,inbox,account]=await Promise.all([api<any>('/experience/feedback?offset='+offset.value+(manage.value?'&admin=true':'')),api<any>('/experience/notices'),api<any>('/product/account')]);if(!scope.valid())return;items.value=list.items;total.value=list.total;notices.value=inbox.items;nextNotices.value=inbox.nextOffset;admin.value=account.role==='ADMIN';if(typeof route.query.receipt==='string'&&!items.value.some(i=>i.id===route.query.receipt)){const receipt=await api<any>('/experience/feedback/'+route.query.receipt);if(scope.valid())items.value.unshift(receipt)}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function submit(){if(busy.value)return;const scope=capture();busy.value=true;error.value='';try{const body={subject:subject.value,description:description.value,attachment:attach.value,context:diagnostics.value?{path:String(route.query.from||'/help/feedback').slice(0,250),...(typeof route.query.task==='string'?{taskId:route.query.task}:{}),device:navigator.userAgent.slice(0,180),appVersion:import.meta.env.VITE_APP_VERSION||'p0p1-candidate'}:{}};const serialized=JSON.stringify(body);if(intentBody!==serialized){intentBody=serialized;key=newKey()}const result=await api<any>('/experience/feedback',{method:'POST',key,body});if(!scope.valid())return;subject.value='';description.value='';attach.value='';key=newKey();intentBody='';notice.value='已提交，回执编号 '+result.id+'。可在下方查看处理结果。';await load()}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function reply(item:any,state:string){const scope=capture();busy.value=true;error.value='';try{await api('/experience/feedback/'+item.id+'/reply',{method:'POST',key:newKey(),body:{expectedVersion:item.version,state,reply:replies.value[item.id]||item.reply}});if(scope.valid())await load()}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function mark(item:any){const scope=capture();try{await api('/experience/notices/'+item.id+'/read',{method:'POST'});if(scope.valid())await load()}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function image(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>250000||!['image/png','image/jpeg','image/webp'].includes(file.type)){error.value='截图请选择小于 250 KB 的 PNG、JPEG 或 WebP。';return}attach.value=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})}
async function seed(){busy.value=true;try{await api('/experience/curated/publish',{method:'POST',key:newKey(),body:{}});notice.value='精选互动作品已准备好，可返回探索查看。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="workspace-page feedback-page"><PageHeader title="反馈与服务通知" description="提交问题、查看私密回执和处理结果。"><RouterLink to="/tasks/activity" class="inline-link">我的任务进度</RouterLink><button v-if="admin" @click="manage=!manage;offset=0;load()">{{manage?'查看我的反馈':'管理全部反馈'}}</button></PageHeader><p v-if="error" class="error" role="alert">{{error}} <button @click="load">重新加载</button></p><p v-if="notice" role="status">{{notice}}</p><section v-if="!manage" class="workspace-card"><h2>遇到了什么问题？</h2><p>只有你和处理问题的管理员可见。诊断信息不包含故事、聊天正文和模型密钥；请勿在描述或截图中填写密码、恢复码或密钥。</p><form @submit.prevent="submit"><label>问题标题<input v-model="subject" required minlength="3" maxlength="120"></label><label>具体情况<textarea v-model="description" required minlength="5" maxlength="4000" rows="5" placeholder="你做了什么、预期发生什么、实际发生什么"></textarea></label><label><input v-model="diagnostics" type="checkbox">附加当前页面、任务编号、应用版本及浏览器信息</label><label>可选截图<input type="file" accept="image/png,image/jpeg,image/webp" @change="image"></label><button v-if="attach" type="button" @click="attach=''">移除截图</button><button class="primary" :disabled="busy">提交并获取回执</button></form></section><section v-if="notices.length&&!manage" class="workspace-card"><h2>服务通知</h2><article v-for="n in notices" :key="n.id"><h3>{{n.title}}{{n.read?'':' · 未读'}}</h3><p>{{n.text}}</p><RouterLink :to="n.path">查看相关页面</RouterLink><button v-if="!n.read" @click="mark(n)">标为已读</button></article><button v-if="nextNotices!==null" @click="olderNotices">更早的服务通知</button></section><section class="workspace-card"><h2>{{manage?'反馈处理':'我的反馈回执'}}</h2><p v-if="!items.length">暂时没有反馈。</p><article v-for="item in items" :key="item.id" :class="{highlight:route.query.receipt===item.id}"><h3>{{item.subject}}</h3><small>回执 {{item.id}} · {{({open:'已收到',investigating:'正在处理',resolved:'已处理'} as Record<string,string>)[item.state]}}</small><p class="pre">{{item.description}}</p><details v-if="manage"><summary>用户同意附加的诊断</summary><p>{{item.context.path}} · {{item.context.taskId||'未关联任务'}} · {{item.context.device}}</p><img v-if="item.context.attachment" :src="item.context.attachment" alt="用户主动附加的截图"></details><blockquote v-if="item.reply">{{item.reply}}</blockquote><template v-if="manage"><label>回复<textarea v-model="replies[item.id]" :placeholder="item.reply||'填写处理情况'" rows="3" maxlength="2000"></textarea></label><button :disabled="busy||!(replies[item.id]||item.reply)" @click="reply(item,'investigating')">回复并标为处理中</button><button :disabled="busy||!(replies[item.id]||item.reply)" @click="reply(item,'resolved')">回复并完成处理</button></template></article><div class="actions"><button :disabled="offset===0" @click="offset=Math.max(0,offset-20);load()">上一页</button><button :disabled="offset+20>=total" @click="offset+=20;load()">下一页</button></div></section><section v-if="admin" class="workspace-card"><h2>内测内容准备</h2><p>首次准备审核过的蓝宝石案和原创互动模板。已有版本不会被覆盖或自动重新上架。</p><button :disabled="busy" @click="seed">准备精选互动作品</button><RouterLink to="/product/admin">配置邀请和查看运行数据</RouterLink></section></div></template>
<style scoped>.feedback-page{max-width:1040px}.workspace-card{margin-top:20px}.feedback-page label{display:block;margin:16px 0}.feedback-page input:not([type=checkbox]),textarea{width:100%}.feedback-page input[type=checkbox]{width:auto}.feedback-page button{min-height:44px;margin:8px 8px 8px 0}.feedback-page article{padding:20px 0;border-bottom:1px solid var(--border,#e8e1d8)}.feedback-page .pre{white-space:pre-wrap;overflow-wrap:anywhere}.feedback-page img{max-width:100%}.highlight{outline:2px solid var(--accent,#b56229);outline-offset:5px}</style>
